    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']
H=len(inp);W=len(inp[0])
seen=set();comps=[]
for i in range(H):
    for j in range(W):
        if inp[i][j] and (i,j) not in seen:
            st=[(i,j)];c=[]
            while st:
                y,x=st.pop()
                if (y,x) in seen: continue
                seen.add((y,x));c.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and inp[ny][nx]: st.append((ny,nx))
            comps.append(c)
# check exact comp sizes/values in demo; then verify test prediction on demo again to ensure correctness
def solve(g):
    H=len(g);W=len(g[0])
    seen=set();comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)];c=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x));c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]: st.append((ny,nx))
                comps.append(c)
    res=[r[:] for r in g]
    # multi-cell comps with exactly one non-(0,3) cell: vertical then horizontal wins at crossings? try both orders.
    verts=[(cx,g[nz[0][0]][nz[0][1]]) for c in comps if len(c)==5 and len([p for p in c if g[p[0]][p[1]] not in (0,3)])==1 for nz in [(p for p in c if g[p[0]][p[1]] not in (0,3))[0]]]
    hz=[(cy,g[nz[0][0]][nz[0][1]]) for c in comps if len(c)==5 and len([p for p in c if g[p[0]][p[1]] not in (0,3)])==1 for nz in [(p for p in c if g[p[0]][p[1]] not in (0,3))[0]]]
    for cx,colv in verts:
        for i in range(H):
            if res[i][cx]==0: res[i][cx]=colv
    for cy,colv in hz:
        for j in range(W):
            if res[cy][j]==0: res[cy][j]=colv
    return res
print(solve(inp)==out)
T=G['Test input']
res=solve(T)
