    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); D=G['Demo pair 4 input']; O=G['Demo pair 4 output']; T=G['Test input']
def findplus(g):
    res=[]
    for i in range(1,len(g)-1):
        for j in range(1,len(g[0])-1):
            nb=[g[a][b] for a,b in [(i-1,j),(i+1,j),(i,j-1),(i,j+1)]]
            if len(set(nb))==1: res.append((i,j,nb[0],g[i][j]))
    return res
def f(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    pls=findplus(g)
    out=[r[:] for r in g]
    for ci,cj,arm,cc in pls:
        if cc==0: continue
        for jj in range(w):
            if out[ci][jj]==0: out[ci][jj]=cc
        for ii in range(h):
            if out[ii][cj]==0: out[ii][cj]=cc
    # skip cells where a real plus' row crosses another real plus' column
    for pi,(ci,cj,a,cc) in enumerate(pls):
        if cc==0: continue
        for qi,q in enumerate(pls):
            if qi==pi or q[3]==0: continue
            r,c=(ci,q[1])
            if out[r][c]!=0: out[r][c]=0
    return out
print('demo:',f(D)==O)
B=f(T)
for r in B: print(''.join(str(x) if x else '.' for x in r))
print(json.dumps(B))

